        let mismatches = Mismatches("portHalfVectorResizingHalfF64ToU16InVectorCode")
        let aInputs = Inputs.conversions(SIMD<Double>.HalfVector.self, seed: 0xC172_99BC_07E8_380E)
            .map(poisoningUpperBytes)
        for a in aInputs {
            let port = { () -> SIMD<UInt16>.HalfVector in
                var a = a
                return withUnsafeTemporaryAllocation(of: SIMD<UInt16>.HalfVector.self, capacity: 1)
                { result in
                    unsafe portHalfVectorResizingHalfF64ToU16InVectorCode(
                        result.baseAddress.unsafelyUnwrapped,
                        resizing: &a
                    )
                    return unsafe result.baseAddress.unsafelyUnwrapped.move()
                }
            }()
            let reference = { () -> SIMD<UInt16>.HalfVector in
                var a = a
                return withUnsafeTemporaryAllocation(of: SIMD<UInt16>.HalfVector.self, capacity: 1)
                { result in
                    unsafe highwayHalfVectorResizingHalfF64ToU16InVectorCode(
                        result.baseAddress.unsafelyUnwrapped,
                        resizing: &a
                    )
                    return unsafe result.baseAddress.unsafelyUnwrapped.move()
                }
            }()
            let definedBytes = SIMD<Double>.HalfVector.laneCount * MemoryLayout<Double>.stride
            let grownBytes = H.HalfVector.laneCount * MemoryLayout<Lane>.stride
            let newBytes = HighwayReference.resizedBytesDefined(
                definedBytes,
                grownBytes,
                MemoryLayout<SIMD<Double>.HalfVector.Raw>.size
            )
            mismatches.check(
                Array(bytes(of: port).prefix(definedBytes)),
                Array(bytes(of: reference).prefix(definedBytes)),
                "a: \(describe(a))"
            )
            mismatches.check(
                Array(registerBytes(of: port).dropFirst(definedBytes).prefix(newBytes)),
                Array(registerBytes(of: reference).dropFirst(definedBytes).prefix(newBytes)),
                "a: \(describe(a))"
            )
        }
        mismatches.record()
    }
}
